24	/** Where Runlog lives when the streamer has not said otherwise. */
25	const DEFAULT_API = "https://runlog.scrthq.com";
26	
27	/**
28	 * What the plugin keeps between launches.
29	 *
30	 * The address and the pinned run, and nothing else: global settings are
31	 * handed to the property inspector, which is a web view, so the session
32	 * never comes near them. It lives in a file of the plugin's own.
33	 */
34	type Globals = { apiBase?: string; pinned?: string | null; switchProfiles?: boolean; profilesOffered?: string[] };
35	
36	let base = DEFAULT_API;
37	
38	/** Whether attaching to a run moves the deck to that run's profile. Unset is on. */
39	let switchProfiles = true;
40	
41	/**
42	 * Where Runlog is, for a key that has to name an address rather than
43	 * press through the wire. The normalized global setting, so a deck
44	 * pointed at a copy of the app opens that copy pages.
45	 */
46	export function apiBase(): string {
47	  return base;
48	}
49	
50	export const store = makeStore();
51	export const wire = openWire((): Account => ({ apiBase: base }), store);
52	
53	/**
54	 * Attaching moves the deck to the profile laid out for the run's pack.
55	 *
56	 * It is the one attach feedback that works on every model, a six-key Mini
57	 * included, and it puts the pack's own moves under the streamer's hand the
58	 * moment a run starts. A pack's profile is not installed until this asks
59	 * for it, which is what keeps forty profiles out of a new install's list.
60	 *
61	 * On the first snapshot of an attach rather than on the attach itself: the
62	 * pack's id travels with the snapshot, and the run's is not known until one
63	 * lands. Once per attach after that, since a snapshot landing is not a
64	 * reason to yank the deck away from wherever the streamer has gone since.
65	 *
66	 * A pack the plugin ships no layout for would land on the generic profile
67	 * with none of its own moves on it. That snapshot has everything a layout
68	 * is built from, so one is built from the run and handed to the Stream Deck
69	 * app to import before the switch. Once per pack, for good: the app's
70	 * import prompt is the streamer's to answer, and asking again on every
71	 * launch fills their list with copies of the one profile.
72	 */
73	let switchedFor: string | null = null;
74	
75	/**
76	 * The packs a profile has been built and handed over for.
77	 *
78	 * In the global settings rather than in memory, so a plugin restart does
79	 * not offer the same pack again. The Open key's "This pack's profile" and
80	 * the Install a profile key are the ways to ask for one again.
81	 */
82	let offered = new Set<string>();
83	
84	/** Writes the pack into the offered list, keeping whatever else is in the settings. */
85	async function markOffered(packId: string): Promise<void> {
86	  if (offered.has(packId)) return;
87	  offered.add(packId);
88	  const settings = await streamDeck.settings.getGlobalSettings<Globals>();
89	  await streamDeck.settings.setGlobalSettings({ ...settings, profilesOffered: [...offered] });
90	}
91	
92	store.subscribe((s) => {
93	  if (!s.attached) {
94	    switchedFor = null;
95	    return;
96	  }
97	  if (!switchProfiles || switchedFor === s.attached || !s.snapshot) return;
98	  switchedFor = s.attached;
99	  const packId = s.snapshot.run?.packId;
100	  const build = packId !== undefined && PACK_PROFILES[packId] === undefined && !offered.has(packId);
101	  if (build) {
102	    const pack = { id: packId, ...(s.snapshot.run?.packTitle ? { title: s.snapshot.run.packTitle } : {}) };
103	    if (hasProfileFor(pack, installedProfiles())) {
104	      // The streamer already has one, imported on some earlier launch or
105	      // from the pack's own page. Handing over another would leave them a
106	      // second copy of a profile they may have rearranged since.
107	      streamDeck.logger.info(`profile: ${packId} already has one in the Stream Deck app`);
108	      void markOffered(packId);
109	      // And nothing is switched: a profile somebody imported is not in this
110	      // plugin's manifest, so it cannot be switched to, and pushing the
111	      // generic layout instead would take the deck off the pack's own keys.
112	      return;
113	    }
114	  }
115	  for (const d of streamDeck.devices) {
116	    const name = profileFor(packId, d.type);
117	    if (!name) continue;
118	    if (build) {
119	      // Marked offered only once a deck has actually been handed a file,
120	      // so a run attached while no deck was plugged in still gets its
121	      // profile when one is.
122	      const built = buildFor(s, d.type);
123	      if (built) {
124	        void markOffered(packId!);
125	        install(built.file);
126	        // The app asks about the profile it was just handed; asking about
127	        // the generic one in the same breath would be two prompts for one
128	        // attach, and the generic layout is the smaller of the two.
129	        continue;
130	      }
131	    }
132	    void streamDeck.profiles.switchToProfile(d.id, name).catch(() => {});
